export type TicketScope = { scope?: string | null; model?: string | null };

/** Short kind of a ticket: its model name, or `Full` for a full (all-models) reset. */
export function ticketKind(ticket: TicketScope | null | undefined): string {
	const model = ticket?.model?.trim();
	if (model && ticket?.scope !== "all") return model;
	return "Full";
}

/** `Fable reset` for a model reset, `Full reset` otherwise (including legacy tickets with no scope). */
export function ticketName(ticket: TicketScope | null | undefined): string {
	return `${ticketKind(ticket)} reset`;
}

/** What spending the ticket does, in words. */
export function ticketEffect(ticket: TicketScope | null | undefined): string {
	const kind = ticketKind(ticket);
	return kind === "Full"
		? "Resets weekly usage now across all models."
		: `Resets the ${kind} allowance now.`;
}

type LiveTicket = TicketScope & { id?: string; resetsLeft?: number; expiresAt?: number };

/** Tickets still spendable at `now`, soonest to expire first. */
export function liveTickets<T extends LiveTicket>(tickets: readonly T[], now: number): T[] {
	return tickets
		.filter((ticket) => {
			if (ticket.resetsLeft != null && ticket.resetsLeft <= 0) return false;
			const expiresMs = ticket.expiresAt == null ? null : resetAtMs(ticket.expiresAt);
			return expiresMs == null || expiresMs > now;
		})
		.sort((a, b) => (resetAtMs(a.expiresAt) ?? Number.POSITIVE_INFINITY) - (resetAtMs(b.expiresAt) ?? Number.POSITIVE_INFINITY));
}

/** The soonest live ticket that clears weekly usage; model resets never drive the weekly chart. */
export function weeklyTicket<T extends LiveTicket>(tickets: readonly T[], now: number): T | undefined {
	return liveTickets(tickets, now).find((ticket) => ticketKind(ticket) === "Full");
}

/** One ticket history row split for a table: verb, `Oct 23`, `00:55`, kind, and `auto`/`manual` (none when it lapsed). */
export function ticketUseParts(use: { at: number; result: string; source: string } & TicketScope): {
	verb: string;
	day: string;
	clock: string;
	kind: string;
	source: string | null;
} {
	const date = new Date(resetAtMs(use.at) ?? 0);
	return {
		verb: TICKET_USE_VERBS[use.result] ?? use.result,
		day: date.toLocaleDateString("en-US", { month: "short", day: "numeric" }),
		clock: date.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit", hourCycle: "h23" }),
		kind: ticketKind(use),
		source: use.result === "expired" ? null : use.source,
	};
}

/** One ticket history row: `Used Oct 23 00:55 · Full reset · auto`. */
export function ticketUseLabel(use: { at: number; result: string; source: string } & TicketScope): string {
	const { verb, day, clock, kind, source } = ticketUseParts(use);
	return source ? `${verb} ${day} ${clock} · ${kind} reset · ${source}` : `${verb} ${day} ${clock} · ${kind} reset`;
}

